$slug = { param($x) $s = (($x.ToLower() -replace "[^a-z0-9]+","-").Trim("-")); if ($s.Length -gt 70) { $s = $s.Substring(0,70) }; $s }
"  saving the smaller placements for all " + $d.Count + " new Pets designs..."
$n = 0; foreach ($k in $d.Keys) { RUN ("SETKV build:" + (& $slug $k) + " " + $d[$k]) | Out-Null; $n++ }
